<script setup>
import { ref, onMounted } from 'vue'
import { api, user } from '../api'
import Button from '../components/ui/Button.vue'
import DataTable from '../components/ui/DataTable.vue'
import Drawer from '../components/ui/Drawer.vue'
import Field from '../components/ui/Field.vue'
import TextInput from '../components/ui/TextInput.vue'
import Tag from '../components/ui/Tag.vue'
import { useAdminStore } from '../store'
const { sources } = useAdminStore()
const emit = defineEmits(['saved', 'error'])
const rows = ref([]), loading = ref(false), problem = ref(''), editing = ref(null), draft = ref(null), busy = ref(false)
const columns = [{ key: 'name', title: '業務' }, { key: 'route', title: '路線' }, { key: 'steps', title: '步驟' }, { key: 'active', title: '狀態' }, { key: 'action', title: '操作' }]
async function load() { loading.value = true; try { rows.value = await api('/work-templates'); problem.value = '' } catch (error) { problem.value = error.message; emit('error', error) } finally { loading.value = false } }
onMounted(load)
function edit(row) { editing.value = row; draft.value = { name: row.name, route: row.route, active: row.active, steps: row.steps.map(step => ({ ...step, documentsText: step.documents?.join('、') || '' })) }; problem.value = '' }
function add() { editing.value = null; draft.value = { name: '', route: '粵港', active: true, steps: [{ title: '', owner: 'us', documentsText: '', days: null }] }; problem.value = '' }
function move(index, offset) { const next = index + offset; if (next < 0 || next >= draft.value.steps.length) return; [draft.value.steps[index], draft.value.steps[next]] = [draft.value.steps[next], draft.value.steps[index]] }
async function save() { busy.value = true; try { const steps = draft.value.steps.map(step => ({ title: step.title, owner: step.owner, documents: step.documentsText.split(/[、,]/).map(item => item.trim()).filter(Boolean), days: step.days === '' || step.days === null ? null : Number(step.days), sourceId: step.sourceId || null })); const body = { name: draft.value.name, steps, active: draft.value.active }; if (!editing.value) { body.route = draft.value.route; body.serviceCode = 'custom' } await api(editing.value ? `/work-templates/${editing.value.id}` : '/work-templates', editing.value ? 'PATCH' : 'POST', body); draft.value = null; await load(); emit('saved', '業務範本已儲存') } catch (error) { problem.value = error.message; emit('error', error) } finally { busy.value = false } }
async function toggle(row) { try { await api(`/work-templates/${row.id}`, 'PATCH', { active: !row.active }); await load(); emit('saved', '範本狀態已更新') } catch (error) { problem.value = error.message; emit('error', error) } }
</script>
<template>
  <section class="panel"><div class="panel-head"><div><h2>業務範本</h2><p>步驟、負責方和預計天數會套用到新工單；舊工單不變。</p></div><Button v-if="user()?.role === 'admin'" variant="primary" @click="add">＋ 自訂業務</Button></div><p v-if="problem" role="alert">{{ problem }} <Button @click="load">重試</Button></p><DataTable :columns="columns" :data="rows" :loading="loading" :min-width="700" empty-text="尚無範本，請新增自訂業務"><template #cell-steps="{ row }">{{ row.steps.length }} 步</template><template #cell-active="{ row }"><Tag :tone="row.active ? 'ok' : 'neutral'">{{ row.active ? '啟用' : '停用' }}</Tag></template><template #cell-action="{ row }"><div v-if="user()?.role === 'admin'" class="row-actions"><button class="text-button" @click="edit(row)">編輯</button><button class="text-button" @click="toggle(row)">{{ row.active ? '停用' : '啟用' }}</button></div><span v-else>僅可查看</span></template></DataTable></section>
  <Drawer :open="!!draft" :title="editing ? '編輯業務範本' : '新增自訂業務'" sub="由上至下依序辦理；客戶步驟會顯示為待客戶提供。" @close="draft = null"><template v-if="draft"><Field label="業務名稱" required><TextInput v-model="draft.name" /></Field><Field v-if="!editing" label="路線"><select v-model="draft.route"><option>粵港</option><option>粵澳</option></select></Field><Field label="狀態"><select v-model="draft.active"><option :value="true">啟用</option><option :value="false">停用</option></select></Field><section v-for="(step, index) in draft.steps" :key="index" class="panel"><div class="panel-head"><div><h2>步驟 {{ index + 1 }}</h2><p>請設定所需資料和預計天數。</p></div><div class="row-actions"><button class="text-button" @click="move(index, -1)">上移</button><button class="text-button" @click="move(index, 1)">下移</button><button v-if="draft.steps.length > 1" class="text-button" @click="draft.steps.splice(index, 1)">移除</button></div></div><Field label="步驟名稱" required><TextInput v-model="step.title" /></Field><Field label="負責方"><select v-model="step.owner"><option value="us">我們</option><option value="client">客戶提供</option></select></Field><Field label="所需文件（以頓號分隔）"><TextInput v-model="step.documentsText" /></Field><Field label="預計天數"><TextInput v-model="step.days" type="number" /></Field><Field label="官方來源"><select v-model="step.sourceId"><option value="">待確認／不指定</option><option v-for="source in sources" :key="source.id" :value="source.id">{{ source.title }}</option></select></Field></section><Button @click="draft.steps.push({ title: '', owner: 'us', documentsText: '', days: null, sourceId: '' })">＋ 增加步驟</Button><p v-if="problem" role="alert">{{ problem }}</p></template><template #footer><Button @click="draft = null">取消</Button><Button variant="primary" :disabled="busy || !draft?.name.trim() || draft?.steps.some(item => !item.title.trim())" @click="save">{{ busy ? '儲存中…' : '儲存範本' }}</Button></template></Drawer>
</template>
